def count_m_fast(A):
    m = 0
    # count subsequences (x, x+1, x+2)
    # Let dp[v][count] be the number of subsequences of length 'count' ending in value 'v'
    # However, the values can be anything. 
    # But we only care about values that can form (x, x+1, x+2).
    # For a fixed x, we want to count (x, x+1, x+2).
    # Let's use a dictionary to store the number of subsequences of length 1 and 2 ending in a value.
    # count1[v] = number of subsequences of length 1 ending in v
    # count2[v] = number of subsequences of length 2 ending in v
    count1 = {}
    count2 = {}
    m = 0
    for x in A:
        # Subsequences of length 3 ending in x:
        # These must be (x-2, x-1, x).
        # The number of such subsequences is the number of subsequences of length 2 ending in x-1.
        if x - 1 in count2:
            m += count2[x - 1]

        # Update count2:
        # Subsequences of length 2 ending in x:
        # These must be (x-1, x).
        # The number of such subsequences is the number of subsequences of length 1 ending in x-1.
        if x - 1 in count1:
            count2[x] = count2.get(x, 0) + count1[x - 1]

        # Update count1:
        # Subsequences of length 1 ending in x:
        # This is just the number of times x has appeared so far.
        count1[x] = count1.get(x, 0) + 1
    return m

def count_n_fast(A):
    # Number of subsequences (x, x+1, x+2, x+3)
    # count3[v] = number of subsequences of length 3 ending in v
    count1 = {}
    count2 = {}
    count3 = {}
    n = 0
    for x in A:
        if x - 1 in count3:
            n += count3[x - 1]

        if x - 1 in count2:
            count3[x] = count3.get(x, 0) + count2[x - 1]

        if x - 1 in count1:
            count2[x] = count2.get(x, 0) + count1[x - 1]

        count1[x] = count1.get(x, 0) + 1
    return n

