def solve_max_m(N):
    # We want to maximize m such that n=0.
    # The best sequences seem to be of the form (1, 1, ..., 1, 2, 2, ..., 2, 3, 3, ..., 3)
    # with k1 ones, k2 twos, and k3 threes.
    # The total number of elements is k1 + k2 + k3 = N.
    # The number of subsequences (1, 2, 3) is k1 * k2 * k3.
    # Let's try all k1, k2, k3 such that k1 + k2 + k3 = N.
    max_m = 0
    for k1 in range(N + 1):
        for k2 in range(N - k1 + 1):
            k3 = N - k1 - k2
            m = k1 * k2 * k3
            if m > max_m:
                max_m = m
    return max_m

