def test_orderings(N):
    results = []
    for k in range(3, 10):
        # For a fixed k, we want to distribute N into k values
        # To maximize m, we want x_i to be as equal as possible
        base = N // k
        rem = N % k
        x = [base + (1 if i < rem else 0) for i in range(k)]

        # Now try different orderings of the values 1, 2, ..., k
        import itertools
        for p in itertools.permutations(range(k)):
            # The arrangement is: x[p[0]] of value p[0], x[p[1]] of value p[1], ...
            # But the values must be consecutive for m to be non-zero.
            # So we should only consider permutations of 0, 1, ..., k-1.
            # Wait, the values are p[0], p[0]+1, p[0]+2, ...
            # Let's just use values 1, 2, 3, ..., k.
            # The sequence is x[p[0]] times 1, x[p[1]] times 2, ..., x[p[k-1]] times k.
            # But the values in m are (v, v+1, v+2).
            # So we want to arrange the values such that no (v, v+1, v+2, v+3) subsequence exists.
            A = []
            for i in range(k):
                A.extend([p[i] + 1] * x[p[i]])

            m, n = count_m_n(A)
            if n == 0:
                results.append((m, k))
    return results

